using System;
using System.IO;

namespace Corvida.Models;

public class AppSettings
{
    public string DataPath { get; set; } = Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "CorvidaData");

    public StorageMode StorageMode { get; set; } = StorageMode.LocalFolder;

    public string? ServerUrl { get; set; }

    /// <summary>
    /// A personal access token for non-interactive clients (the MCP server), generated by an
    /// administrator. Null means "no credentials", which is all that is needed while the server
    /// does not require login.
    /// </summary>
    public string? ApiKey { get; set; }
}
